import{_ as e,c as i,o as t,ag as s}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"隱私選擇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/privacy-choices.md","filePath":"zh-TW/guide/privacy-choices.md","lastUpdated":1791311600000}'),r={name:"zh-TW/guide/privacy-choices.md"};function l(n,a,h,o,c,d){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="隱私選擇" tabindex="-1">隱私選擇 <a class="header-anchor" href="#隱私選擇" aria-label="Permalink to &quot;隱私選擇&quot;">​</a></h1><p>nPlyr 是一款本機優先的應用程式。由於你的資料留在你的裝置上，我們不會收集、出售或共享任何個人資訊。</p><h2 id="我們本機儲存的資料" tabindex="-1">我們本機儲存的資料 <a class="header-anchor" href="#我們本機儲存的資料" aria-label="Permalink to &quot;我們本機儲存的資料&quot;">​</a></h2><p>nPlyr 將所有資料本機儲存在你的裝置上：</p><ul><li>觀看歷程、書籤與下載內容</li><li>應用程式偏好與主題</li><li>小程式變數（僅在本機儲存中，且僅來自你匯入的規則）</li><li>偵錯日誌（若啟用）</li></ul><p>這些資料都不會被應用程式本身上傳到任何伺服器。</p><h2 id="網路由使用者主導" tabindex="-1">網路由使用者主導 <a class="header-anchor" href="#網路由使用者主導" aria-label="Permalink to &quot;網路由使用者主導&quot;">​</a></h2><p>nPlyr 僅在串流媒體、下載、瀏覽或執行你選擇的某個小程式時使用網路。沒有雲端 AI 功能，也沒有帳號，因此沒有需要選擇加入或退出的事項——應用程式根本不會把你的資料傳送給我們。</p><h2 id="你的權利" tabindex="-1">你的權利 <a class="header-anchor" href="#你的權利" aria-label="Permalink to &quot;你的權利&quot;">​</a></h2><p>由於 nPlyr 不在我們的伺服器上收集或儲存個人資料，也就沒有可供我們存取、刪除或轉移的個人資料。你所有的資料都可以在應用程式內直接管理，或透過移除應用程式的容器資料夾來管理：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nPlyr</span></span></code></pre></div><h2 id="不出售" tabindex="-1">不出售 <a class="header-anchor" href="#不出售" aria-label="Permalink to &quot;不出售&quot;">​</a></h2><p>nPlyr 不出售任何個人資訊。我們不使用任何第三方的分析、廣告或追蹤服務。</p><h2 id="聯絡" tabindex="-1">聯絡 <a class="header-anchor" href="#聯絡" aria-label="Permalink to &quot;聯絡&quot;">​</a></h2><p>如果你對隱私選擇有疑問，請在以下地址提交 issue： <code>https://github.com/nPlyr/nPlyr-site/issues</code></p>',15)])])}const b=e(r,[["render",l]]);export{u as __pageData,b as default};
